      last_evaluated_date: ['']
    });
  }
  ngOnInit() {
    this.loadEmployees();
    this.loadSkillsData();
    this.loadJobDescriptions();
  }
  // ==================== CRUD EMPLOYÉS ====================
  loadEmployees() {
    this.loading = true;
    this.errorMessage = null;
    this.employeeService.getEmployees().subscribe({
      next: employees => {
        this.employees = employees;
        this.filteredEmployees = [...employees];
        this.extractFilterOptions();
        this.loading = false;
      },
      error: err => {
        console.error('Error loading employees:', err);
        this.errorMessage = 'Erreur lors du chargement des employés.';
        this.loading = false;
      }
    });
  }
  showAddEmployeeForm() {
    this.showAddForm = true;
    this.editingEmployee = null;
    this.employeeForm.reset();
    this.clearSkillsArray();
    this.clearMessages();
  }
  editEmployee(employee) {
    this.editingEmployee = employee;
    this.showAddForm = true;
    this.employeeForm.patchValue({
      name: employee.name,
      position: employee.position,
      email: employee.email,
      hire_date: employee.hire_date,
      phone: employee.phone || '',
      gender: employee.gender || '',
      location: employee.location || '',
      department: employee.department || '',
      notes: employee.notes || ''
    });
    this.clearSkillsArray();
    if (employee.skills && employee.skills.length > 0) {
      employee.skills.forEach(empSkill => {
        this.addSkillToForm(empSkill);
      });
    }
    this.clearMessages();
  }
  onEmployeeSubmit() {
    if (this.employeeForm.valid) {
      this.savingEmployee = true;
      this.errorMessage = null;
      this.successMessage = null;
      const formValue = this.employeeForm.value;
      const skillsData = formValue.skills.filter(skill => skill.skill_id && skill.actual_skill_level_id).map(skill => ({
        skill_id: parseInt(skill.skill_id, 10),
        actual_skill_level_id: parseInt(skill.actual_skill_level_id, 10),
        acquired_date: skill.acquired_date || null,
        certification: skill.certification || null,
        last_evaluated_date: skill.last_evaluated_date || null
      }));
      const employeeData = {
        name: formValue.name,
        position: formValue.position,
        email: formValue.email,
        hire_date: formValue.hire_date,
        phone: formValue.phone || '',
        gender: formValue.gender || '',
        location: formValue.location || '',
        department: formValue.department || '',
        notes: formValue.notes || '',
        skills: skillsData
      };
      console.log('Employee data being sent:', JSON.stringify(employeeData, null, 2));
      console.log('Form validation status:', this.employeeForm.valid);
      console.log('Form errors:', this.employeeForm.errors);
      console.log('Individual field errors:');
      Object.keys(this.employeeForm.controls).forEach(key => {
        const control = this.employeeForm.get(key);
        if (control?.errors) {
          console.log(`${key}:`, control.errors);
        }
      });
      if (this.editingEmployee) {
        this.employeeService.updateEmployee(this.editingEmployee.id, employeeData).subscribe({
          next: updatedEmployee => {
            const index = this.employees.findIndex(emp => emp.id === updatedEmployee.id);
            if (index !== -1) {
              this.employees[index] = updatedEmployee;
            }
            this.applyFilters();
            this.successMessage = 'Employé mis à jour avec succès';
            this.cancelEmployeeEdit();
            this.savingEmployee = false;
          },
          error: err => {
            console.error('Error updating employee:', err);
            console.error('Full error object:', err);
            console.error('Error details:', err.error?.details);
            let errorMsg = 'Erreur lors de la mise à jour de l\'employé';
            if (err.error?.details && Array.isArray(err.error.details)) {
              errorMsg = err.error.details.join(', ');
            } else if (err.error?.message) {
              errorMsg = err.error.message;
            }
            this.errorMessage = errorMsg;
            this.savingEmployee = false;
          }
        });
      } else {
        this.employeeService.createEmployee(employeeData).subscribe({
          next: newEmployee => {
            this.employees.push(newEmployee);
            this.applyFilters();
            this.extractFilterOptions();
            this.successMessage = 'Employé créé avec succès';
            this.cancelEmployeeEdit();
            this.savingEmployee = false;
          },
          error: err => {
            console.error('Error creating employee:', err);
            console.error('Full error object:', err);
            console.error('Error status:', err.status);
            console.error('Error details:', err.error);
            console.error('Validation details:', err.error?.details);
            let errorMsg = 'Erreur lors de la création de l\'employé';
            if (err.error?.details && Array.isArray(err.error.details)) {
              errorMsg = err.error.details.join(', ');
            } else if (err.error?.message) {
              errorMsg = err.error.message;
            } else if (err.message) {
              errorMsg = err.message;
            }
            this.errorMessage = errorMsg;
            this.savingEmployee = false;
          }
        });
      }
    } else {
      console.log('Form is invalid:', this.employeeForm.errors);
      console.log('Form value:', this.employeeForm.value);
      console.log('Form validation details:');
      Object.keys(this.employeeForm.controls).forEach(key => {
        const control = this.employeeForm.get(key);
        if (control?.invalid) {
          console.log(`${key} is invalid:`, control.errors);
        }
      });
      // Mark all fields as touched to show validation errors
      Object.keys(this.employeeForm.controls).forEach(key => {
        const control = this.employeeForm.get(key);
        control?.markAsTouched();
      });
      this.errorMessage = 'Veuillez remplir tous les champs obligatoires correctement.';
    }
  }
  deleteEmployee(employee) {
    if (window.confirm(`Êtes-vous sûr de vouloir supprimer ${employee.name} et toutes ses compétences ?`)) {
      this.employeeService.deleteEmployee(employee.id).subscribe({
        next: () => {
          this.employees = this.employees.filter(emp => emp.id !== employee.id);
          this.applyFilters();
          this.extractFilterOptions();
          this.successMessage = 'Employé supprimé avec succès';
          this.errorMessage = null;
        },
        error: err => {
          console.error('Error deleting employee:', err);
          this.errorMessage = 'Erreur lors de la suppression de l\'employé.';
        }
      });
    }
  }
